# Lightweight escaped rendering of our authored guide text. No scripts or remote media.
import re
def inline(s):
 s=escape(s)
 def link(m):
  import os
  url=m.group(2)
  if not url.startswith(('https://','http://')):
   target=(Path('docs/salesforce/guides')/url).resolve()
   if target.parent==Path('docs/salesforce/guides').resolve() and target.suffix=='.md': url='guide-'+target.stem+'.html'
   else: url=os.path.relpath(target,root.resolve())
  return '<a href="'+url+'">'+m.group(1)+'</a>'
 s=re.sub(r'\[([^]]+)\]\(([^ )]+)\)',link,s)
 s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
 s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
 return s
for p in Path('docs/salesforce/guides').glob('*.md'):
 chunks=[];code=False;buf=[]
 for line in p.read_text().splitlines():
  if line.startswith('```'):
   if code:chunks.append('<pre><code>'+escape('\n'.join(buf))+'</code></pre>');buf=[]
   code=not code;continue
  if code:buf.append(line);continue
  if line.startswith('# '):chunks.append('<h1>'+inline(line[2:])+'</h1>')
  elif line.startswith('## '):chunks.append('<h2>'+inline(line[3:])+'</h2>')
  elif line:chunks.append('<p>'+inline(line)+'</p>')
 # Relative source links stay in the source document, avoiding broken copied paths.
 body=section('<article class="article"><p class="eyebrow">Salesforce guide · starter content</p>'+''.join(chunks)+'<p><a href="../../docs/salesforce/guides/'+p.name+'">Open source Markdown and related links</a></p></article>')
 page('guide-'+p.stem+'.html',p.read_text().splitlines()[0][2:],'Practical Salesforce starter guide with explicit context and evidence requirements.',body)
